"""Dev tool: pull every code/markdown cell out of the workshop notebook, verbatim,
into hlh/cells.py (keyed by cell id) so the app runs *exactly* the workshop code.

    python tools/extract_cells.py path/to/half_life_hacker.ipynb
"""
import json, sys, pprint, pathlib

nb_path = pathlib.Path(sys.argv[1])
nb = json.loads(nb_path.read_text(encoding="utf-8"))
cells = {c["id"]: "".join(c["source"]) for c in nb["cells"]}
out = pathlib.Path(__file__).resolve().parent.parent / "hlh" / "cells.py"
out.write_text(
    '"""AUTO-GENERATED by tools/extract_cells.py from the workshop notebook. Do not edit."""\n'
    "CELLS = " + pprint.pformat(cells, width=100, sort_dicts=False) + "\n",
    encoding="utf-8",
)
print(f"wrote {out}  ({len(cells)} cells)")
